import CoreText
import UIKit

/// The reference's icon set (Ionicons 7, MIT, as shipped in @expo/vector-icons): the very font the previous app drew
/// its icons with, so an icon here is the reference's glyph, not a look-alike symbol. `IonIcon.image("headset", size: 24)`
/// gives a template image `size` points square — the glyph's own 512-unit box, as `<Ionicons size={24}>` draws it.
enum IonIcon {
    private static var registered = false
    private static var cache: [String: UIImage] = [:]
    private static var codes: [String: UInt32] = {
        var table: [String: UInt32] = [:]
        for pair in glyphs.split(separator: ";") {
            let parts = pair.split(separator: ":")
            if parts.count == 2, let code = UInt32(parts[1], radix: 16) { table[String(parts[0])] = code }
        }
        return table
    }()

    private static func font(_ size: CGFloat) -> CTFont? {
        if !registered {
            registered = true
            if let address = Bundle.main.url(forResource: "Ionicons", withExtension: "ttf") {
                _ = CTFontManagerRegisterFontsForURL(address as CFURL, .process, nil)
            }
        }
        guard UIFont(name: "Ionicons", size: size) != nil else { return nil }
        return CTFontCreateWithName("Ionicons" as CFString, size, nil)
    }

    /// Whether the set has a glyph of that name.
    static func has(_ name: String) -> Bool { return codes[name] != nil }

    /// The glyph's outline in a box `size` points square (y down), or nil when the name or the font is missing.
    static func path(_ name: String, size: CGFloat) -> CGPath? {
        guard let code = codes[name], let font = font(size), let scalar = UnicodeScalar(code) else { return nil }
        var chars = Array(String(Character(scalar)).utf16)
        var glyph = CGGlyph(0)
        guard CTFontGetGlyphsForCharacters(font, &chars, &glyph, 1), let outline = CTFontCreatePathForGlyph(font, glyph, nil) else { return nil }
        // The font's box: 512 units wide, from 448 above the baseline to 64 below it (the icon fills that square).
        var flip = CGAffineTransform(a: 1, b: 0, c: 0, d: -1, tx: 0, ty: size * 448 / 512)
        return outline.copy(using: &flip)
    }

    /// A template image of the glyph, `size` points square; an empty image when the name is unknown.
    static func image(_ name: String, size: CGFloat) -> UIImage {
        let key = "\(name)@\(size)"
        if let made = cache[key] { return made }
        let shape = path(name, size: size)
        let made = UIGraphicsImageRenderer(size: CGSize(width: size, height: size)).image { (context: UIGraphicsImageRendererContext) -> Void in
            guard let shape = shape else { return }
            context.cgContext.addPath(shape)
            context.cgContext.setFillColor(UIColor.black.cgColor)
            context.cgContext.fillPath(using: .winding)
        }.withRenderingMode(.alwaysTemplate)
        cache[key] = made
        return made
    }

